import {NATIVE_GROUNDS,NATIVE_MAPS,NATIVE_TERRAINS,NATIVE_GROUND_BUILD,nativeTerrainId,nativeGroundRGB,applyNativeEnvironment,lightingSettings,nightness,ambientRGB} from './runtime.mjs';
const VN={camp:'Trại giữa rừng',meadow:'Đồng cỏ ánh trăng',woods:'Rừng nấm phát sáng',canyon:'Vách đá đỏ',farm:'Nông trại bí ngô',marsh:'Đầm lầy suối trong',graveyard:'Đồi nghĩa địa',burnt:'Rừng cháy',wind:'Vách núi gió',prime:'Rừng nguyên sinh',swamp:'Đầm lầy độc',lake:'Hồ sương',volcano:'Núi lửa',road:'Đường di cư',salt:'Cầu muối',peak:'Đỉnh núi tuyết',nroad:'Đường phương Bắc',outer:'Ngoại thành',canal:'Khu kênh đào',isle:'Đảo giữa hồ',dark:'Rừng tối',cathedral:'Khu thánh đường',farm2:'Nông trại bỏ hoang',meadow2:'Đồi hoa đêm',marsh2:'Đầu nguồn',marsh3:'Thác đom đóm',graveyard2:'Nghĩa địa sau đồi',woods2:'Rừng nấm sâu',wind2:'Đảo đá gió',swamp2:'Rễ cây độc',canyon2:'Mỏ tinh thể cam',canyon3:'Lõi hẻm núi',prime2:'Hồ trứng rồng',cornmaze:'Mê cung ngô',pens:'Chuồng trại bỏ hoang'};
export function mountNativePalette(h){
 const $=id=>document.getElementById(id),box=document.createElement('div');box.className='native-palette';box.innerHTML=`<h3>Nền gốc Night Camp</h3><input id="nativeSearch" type="search" aria-label="Tìm màu theo map" placeholder="Tìm: tuyết, đầm lầy, peak, tên map…"><label>Map nguồn<select id="nativeMap"></select></label><div class="native-previews"><figure><canvas id="nativeDay" width="96" height="48"></canvas><figcaption>Ngày · ánh sáng gốc</figcaption></figure><figure><canvas id="nativeNight" width="96" height="48"></canvas><figcaption>Đêm · ánh sáng gốc</figcaption></figure></div><p id="nativeInfo" class="hint"></p><label><input id="nativeLighting" type="checkbox" checked> Dùng sắc sáng / độ tối riêng của map</label><label><input id="nativeSeed" type="checkbox" checked> Dùng seed gốc để pha mảng nền</label><button id="nativeApply" class="primary">Áp dụng bảng màu & ánh sáng</button><p class="hint">Đổi màu nền thủ tục đang có; giữ ảnh riêng, vật thể, tuyến đường và vùng cản. Giữ giờ đang xem, đưa ánh sáng môi trường về 100%. Có Hoàn tác. Hoặc chọn một màu dưới đây để tô từng vùng.</p><div id="nativeColors" class="terrain-list"></div><p class="hint">Màu lấy từ mã client lưu trong repo, không lấy màu minimap. Không tự thêm cây, đèn, sương hay bố cục của game gốc.</p><hr>`;document.querySelector('[data-panel="terrain"]').prepend(box);
 let chosen='meadow',observed=null,listing=false;const labels=m=>VN[m.id]||((VN[m.root]||m.root||'Khu phụ')+(m.bn?' B'+m.bn:'')+' · '+m.name),on=(id,event,fn)=>$(id).addEventListener(event,h.safe(fn));
 function list(){const q=$('nativeSearch').value.trim().toLocaleLowerCase(),groups={camp:'Trại',field:'Khu chính',section:'Khu phụ B',dungeon:'Phụ bản'};const rows=Object.values(NATIVE_MAPS).filter(m=>(labels(m)+' '+m.id+' '+m.name).toLocaleLowerCase().includes(q));$('nativeMap').replaceChildren();for(const [key,label]of Object.entries(groups)){const group=document.createElement('optgroup');group.label=label;for(const m of rows.filter(m=>m.category===key))group.append(new Option(labels(m)+' ['+m.id+']',m.id));if(group.children.length)$('nativeMap').append(group)}if(!rows.some(m=>m.id===chosen)&&rows.length)chosen=rows[0].id;$('nativeMap').value=chosen;$('nativeApply').disabled=!rows.length;listing=!!rows.length}
 function example(mode){const p=h.state.project||{},m=NATIVE_MAPS[chosen];return {...p,seed:$('nativeSeed').checked?m.seed:p.seed,environment:{map:chosen,nativeLighting:$('nativeLighting').checked},lighting:{...lightingSettings(p),mode,ambient:1,vignette:false,playerLight:false}}}
 function refresh(){
  if(!h.state.project)return;const env=h.state.project.environment;$('nightPreset').textContent=env?'☾ Mẫu đêm · map đang chọn':'☾ Mẫu đêm · đồng cỏ';if(env?.map!==observed){observed=env?.map;if(observed){chosen=observed;$('nativeLighting').checked=env.nativeLighting;list()}}if(!listing)list();const m=NATIVE_MAPS[chosen],b=NATIVE_GROUNDS[m.biome];$('nativeInfo').textContent=Object.keys(NATIVE_MAPS).length+' map · '+m.name+' · '+m.id+' · '+b.source+' · '+NATIVE_GROUND_BUILD+' · seed '+m.seed+(m.dusk?' · tối nền tối thiểu '+Math.round(m.dusk*100)+'%':'');
  const base=b.kind==='dungeon'?'floor':'base';for(const [id,mode]of [['nativeDay','day'],['nativeNight','night']]){const p=example(mode),n=nightness(p),amb=ambientRGB(p),c=$(id),cc=c.getContext('2d'),data=cc.createImageData(96,48);for(let y=0;y<48;y++)for(let x=0;x<96;x++){const rgb=nativeGroundRGB(m.biome,base,x/96*m.width,y/48*m.height,p.seed,n).map((v,i)=>Math.round(v*amb[i]/255));data.data.set([...rgb,255],(y*96+x)*4)}cc.putImageData(data,0,0)}
  const p=example(lightingSettings(h.state.project).mode),n=nightness(p),amb=ambientRGB(p);$('nativeColors').replaceChildren(...Object.entries(NATIVE_TERRAINS).filter(([,v])=>v.biome===m.biome).map(([id,v])=>{const bt=document.createElement('button');bt.dataset.nativeTerrain=id;bt.className=h.state.terrain===id?'selected':'';const sw=document.createElement('span');sw.className='swatch';sw.style.background=`rgb(${nativeGroundRGB(m.biome,v.channel,200,200,p.seed,n).map((c,i)=>Math.round(c*amb[i]/255)).join(',')})`;bt.append(sw,document.createTextNode(v.name));bt.onclick=()=>{h.state.terrain=id;$('tool').value='paint';refresh();h.message('Nền gốc '+labels(m)+' · '+v.name+' · kéo trên map để tô; dùng Áp dụng để đồng bộ ánh sáng map nguồn.')};return bt}));
 }
 on('nativeSearch','input',()=>{list();refresh()});on('nativeMap','change',()=>{chosen=$('nativeMap').value;refresh()});on('nativeSeed','change',refresh);on('nativeLighting','change',()=>{if(h.state.project.environment?.map===chosen)h.update(p=>p.environment.nativeLighting=$('nativeLighting').checked);else refresh()});
 on('nativeApply','click',()=>{h.stop();const id=chosen;h.update(p=>{Object.assign(p,applyNativeEnvironment(p,id,{nativeLighting:$('nativeLighting').checked,useSeed:$('nativeSeed').checked}));p.lighting={...lightingSettings(p),ambient:1}});h.state.terrain=nativeTerrainId(NATIVE_MAPS[id].biome,NATIVE_GROUNDS[NATIVE_MAPS[id].biome].kind==='dungeon'?'floor':'base');refresh();h.message('Đã áp dụng màu gốc '+labels(NATIVE_MAPS[id])+'. Giữ vật thể, đường, ảnh riêng và vùng cản; có thể Hoàn tác.')});
 list();return {refresh};
}
